1	package registry_test
2	
3	import (
4		"os"
5		"path/filepath"
6		"strconv"
7		"strings"
8		"testing"
9	
10		"github.com/okf-memory/okf-agent-memory/pkg/registry"
11	)
12	
13	func TestValidateBundleID(t *testing.T) {
14		for _, id := range []string{
15			"nextjs-15",
16			"peter/django-5-rules",
17			"@peter/django-5-rules",
18			"acme/tools/linter",
19			"weird..name",
20			"a.b/c.d",
21			"Ünïcode bundle/name",
22		} {
23			if err := registry.ValidateBundleID(id); err != nil {
24				t.Errorf("legitimate id %q refused: %v", id, err)
25			}
26		}
27	
28		for _, tc := range []struct{ id, reason string }{
29			{"", "empty id"},
30			{"..", "parent directory traversal"},
31			{"../outside", "parent directory traversal"},
32			{"../../../outside-reg/planted", "parent directory traversal"},
33			{"acme/../../x", "parent directory traversal"},
34			{"acme/..", "parent directory traversal"},
35			{"/etc/okf", "absolute path"},
36			{"/", "absolute path"},
37			{"acme//rules", "non-canonical path"},
38			{"acme/", "non-canonical path"},
39			{"./acme", "non-canonical path"},
40			{"acme/./rules", "non-canonical path"},
41			{".", "non-canonical path"},
42			{`acme\rules`, "backslash"},
43			{`..\outside`, "backslash"},
44			{"acme\x00rules", "NUL byte"},
45		} {
46			err := registry.ValidateBundleID(tc.id)
47			if err == nil {
48				t.Errorf("unsafe id %q accepted", tc.id)
49				continue
50			}
51			if !strings.Contains(err.Error(), strconv.Quote(tc.id)) || !strings.Contains(err.Error(), tc.reason) {
52				t.Errorf("id %q: error %q must name the value and the reason %q", tc.id, err, tc.reason)
53			}
54		}
55	}
56	
57	// vendorWorkspace returns a resolved workspace path and a sibling outside dir.
58	func vendorWorkspace(t *testing.T) (ws, outside string) {
59		t.Helper()
60		base, err := filepath.EvalSymlinks(t.TempDir())
61		if err != nil {
62			t.Fatal(err)
63		}
64		ws, outside = filepath.Join(base, "ws"), filepath.Join(base, "outside")
65		for _, d := range []string{ws, outside} {
66			if err := os.MkdirAll(d, 0o755); err != nil {
67				t.Fatal(err)
68			}
69		}
70		return ws, outside
71	}
72	
73	func mustMkdir(t *testing.T, p string) {
74		t.Helper()
75		if err := os.MkdirAll(p, 0o755); err != nil {
76			t.Fatal(err)
