31	func ridArchive(t *testing.T, files ...ridFile) []byte {
32		t.Helper()
33		var buf bytes.Buffer
34		gw := gzip.NewWriter(&buf)
35		tw := tar.NewWriter(gw)
36		for _, f := range files {
37			if err := tw.WriteHeader(&tar.Header{Name: f.name, Mode: 0o644, Size: int64(len(f.body)), Typeflag: tar.TypeReg}); err != nil {
38				t.Fatal(err)
