41				t.Fatal(err)
42			}
43		}
44		if err := tw.Close(); err != nil {
45			t.Fatal(err)
46		}
47		if err := gw.Close(); err != nil {
48			t.Fatal(err)
49		}
50		return buf.Bytes()
51	}
