53	// ridRegistry serves /bundles/<slug>.json manifests (raw JSON) and
54	// /<name>.tar.gz archives through the registry client factory.
55	func ridRegistry(t *testing.T, manifests map[string]string, archives map[string][]byte) {
56		t.Helper()
57		handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
58			if m, ok := manifests[strings.TrimSuffix(strings.TrimPrefix(r.URL.Path, "/bundles/"), ".json")]; ok && strings.HasPrefix(r.URL.Path, "/bundles/") {
59				_, _ = io.WriteString(w, m)
60				return
61			}
62			if a, ok := archives[strings.TrimPrefix(r.URL.Path, "/")]; ok {
63				_, _ = w.Write(a)
64				return
65			}
66			http.NotFound(w, r)
67		})
68		orig := newRegistryClient
69		t.Cleanup(func() { newRegistryClient = orig })
70		newRegistryClient = func(baseURL string) *registry.Client {
71			c := registry.NewClient(baseURL)
72			c.HTTPClient.Transport = roundTripFunc(func(req *http.Request) (*http.Response, error) {
73				rec := httptest.NewRecorder()
74				handler.ServeHTTP(rec, req)
75				return rec.Result(), nil
76			})
77			return c
78		}
79	}
