409		for _, p := range []string{"@peter/django-5-rules/index.md", "acme/tools/linter/index.md"} {
410			if _, err := os.Stat(filepath.Join(ws, ".okf", "vendor", filepath.FromSlash(p))); err != nil {
411				t.Fatalf("expected legitimate install at .okf/vendor/%s: %v", p, err)
412			}
413		}
414	
415		// Failing install next to a sibling: own dir removed, sibling and shared parent kept.
416		if code, _ := ridRun(t, "pull", "--registry", "https://registry.test", "acme/tools/broken"); code != 1 {
417			t.Fatalf("expected invalid bundle to be rolled back with exit 1, got %d", code)
418		}
419		if _, err := os.Stat(filepath.Join(ws, ".okf", "vendor", "acme", "tools", "broken")); !os.IsNotExist(err) {
420			t.Fatalf("rolled-back bundle dir must be removed: %v", err)
421		}
422		if _, err := os.Stat(filepath.Join(ws, ".okf", "vendor", "acme", "tools", "linter", "index.md")); err != nil {
423			t.Fatalf("sibling bundle must survive rollback: %v", err)
424		}
425	
426		// Failing install alone in its scope: the now-empty parent is cleaned up.
427		if code, _ := ridRun(t, "pull", "--registry", "https://registry.test", "solo/broken"); code != 1 {
428			t.Fatalf("expected invalid bundle to be rolled back with exit 1, got %d", code)
429		}
430		if _, err := os.Stat(filepath.Join(ws, ".okf", "vendor", "solo")); !os.IsNotExist(err) {
431			t.Fatalf("empty scope dir must be cleaned up after rollback: %v", err)
432		}
433	
434		// vendor remove still works for both forms of a scoped id.
435		if code, stderr := ridRun(t, "vendor", "remove", "acme/tools/linter"); code != 0 {
436			t.Fatalf("vendor remove: exit %d, stderr %q", code, stderr)
437		}
438		if _, err := os.Stat(filepath.Join(ws, ".okf", "vendor", "acme", "tools", "linter")); !os.IsNotExist(err) {
439			t.Fatalf("vendor remove must delete the bundle: %v", err)
440		}
441		ridAssertOutside(t, outside, map[string]string{})
442	}
443

