package lock

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

type BundleEntry struct {
	ID          string    `json:"id"`
	Source      string    `json:"source"`
	Version     string    `json:"version"`
	Hash        string    `json:"hash"`
	InstalledAt time.Time `json:"installed_at"`
}

type Lockfile struct {
	Version int           `json:"version"`
	Bundles []BundleEntry `json:"bundles"`
}

func (lf *Lockfile) Upsert(entry BundleEntry) {
	for i, b := range lf.Bundles {
		if b.ID == entry.ID {
			lf.Bundles[i] = entry
			return
		}
	}
	lf.Bundles = append(lf.Bundles, entry)
}

func (lf *Lockfile) Remove(id string) bool {
	for i, b := range lf.Bundles {
		if b.ID == id {
			lf.Bundles = append(lf.Bundles[:i], lf.Bundles[i+1:]...)
			return true
		}
	}
	return false
}

func ReadLockfile(path string) (*Lockfile, error) {
	cleanPath := filepath.Clean(path)
	// #nosec G304 -- lockfile path is provided by caller or default workspace okf.lock
	f, err := os.Open(cleanPath)
	if err != nil {
		if os.IsNotExist(err) {
			return &Lockfile{Version: 1}, nil
		}
		return nil, err
	}
	defer func() { _ = f.Close() }()

	lf := &Lockfile{Version: 1}
	scanner := bufio.NewScanner(f)
	var current *BundleEntry

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "version:") {
			_, _ = fmt.Sscanf(line, "version: %d", &lf.Version)
			continue
		}
		if strings.HasPrefix(line, "- id:") {
			if current != nil {
				lf.Bundles = append(lf.Bundles, *current)
			}
			val := strings.TrimSpace(strings.TrimPrefix(line, "- id:"))
			val = strings.Trim(val, `"'`)
			current = &BundleEntry{ID: val}
			continue
		}
		if current != nil {
			parts := strings.SplitN(line, ":", 2)
			if len(parts) == 2 {
				k := strings.TrimSpace(parts[0])
				v := strings.Trim(strings.TrimSpace(parts[1]), `"'`)
				switch k {
				case "source":
					current.Source = v
				case "version":
					current.Version = v
				case "hash":
					current.Hash = v
				case "installed_at":
					t, _ := time.Parse(time.RFC3339, v)
					current.InstalledAt = t
				}
			}
		}
	}
	if current != nil {
		lf.Bundles = append(lf.Bundles, *current)
	}

	return lf, scanner.Err()
}

func WriteLockfile(path string, lf *Lockfile) error {
	cleanPath := filepath.Clean(path)
	// #nosec G304 -- lockfile path is provided by caller or default workspace okf.lock
	f, err := os.Create(cleanPath)
	if err != nil {
		return err
	}
	defer func() { _ = f.Close() }()

	w := bufio.NewWriter(f)
	if _, err := fmt.Fprintf(w, "# okf.lock - Generated by OKF Agent Memory. DO NOT EDIT MANUALLY.\n"); err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "version: %d\n", lf.Version); err != nil {
		return err
	}
	if _, err := fmt.Fprintf(w, "bundles:\n"); err != nil {
		return err
	}
	for _, b := range lf.Bundles {
		if _, err := fmt.Fprintf(w, "  - id: %q\n", b.ID); err != nil {
			return err
		}
		if _, err := fmt.Fprintf(w, "    source: %q\n", b.Source); err != nil {
			return err
		}
		if _, err := fmt.Fprintf(w, "    version: %q\n", b.Version); err != nil {
			return err
		}
		if _, err := fmt.Fprintf(w, "    hash: %q\n", b.Hash); err != nil {
			return err
		}
		if _, err := fmt.Fprintf(w, "    installed_at: %q\n", b.InstalledAt.UTC().Format(time.RFC3339)); err != nil {
			return err
		}
	}
	return w.Flush()
}

package cli

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/okf-memory/okf-agent-memory/pkg/lock"
	"github.com/okf-memory/okf-agent-memory/pkg/okf"
	"github.com/okf-memory/okf-agent-memory/pkg/registry"
)

func printRestoreUsage() {
	fmt.Println(`Usage:
  okf restore [flags]

Restores all vendor bundles specified in okf.lock.

Flags:
  --registry <url>   Override canonical registry endpoint (default: https://registry.okf-memory.dev)
  --min-score <N>    Gate minimum bundle quality score (0-100; aborts installation if below)
  --force            Reinstall all bundles even if already present

Examples:
  okf restore
  okf restore --min-score 80
  okf restore --force`)
}

func cmdRestore(args []string) {
	fs := flag.NewFlagSet("restore", flag.ExitOnError)
	registryURL := fs.String("registry", registry.DefaultRegistryURL, "Registry endpoint")
	minScore := fs.Int("min-score", 0, "Gate minimum bundle quality score (0-100)")
	force := fs.Bool("force", false, "Reinstall existing vendor bundles")
	fs.Usage = printRestoreUsage

	if err := fs.Parse(args); err != nil {
		os.Exit(2)
	}

	if *minScore < 0 || *minScore > 100 {
		fmt.Fprintf(os.Stderr, "Error: --min-score must be an integer between 0 and 100\n")
		exitFunc(2)
		return
	}

	if _, err := os.Stat("okf.lock"); os.IsNotExist(err) {
		fmt.Fprintln(os.Stderr, "Error: okf.lock not found. Run 'okf pull <bundle-id>' to install a bundle.")
		exitFunc(1)
		return
	}

	runRestore(*registryURL, *force, *minScore)
}

func runRestore(registryURL string, force bool, minScores ...int) {
	minScore := 0
	if len(minScores) > 0 {
		minScore = minScores[0]
	}

	lf, err := lock.ReadLockfile("okf.lock")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading okf.lock: %v\n", err)
		exitFunc(1)
		return
	}

	if lf == nil || len(lf.Bundles) == 0 {
		fmt.Println("No vendor bundles specified in okf.lock.")
		return
	}

	client := newRegistryClient(registryURL)
	restoredCount := 0
	skippedCount := 0

	for _, entry := range lf.Bundles {
		// okf.lock may come from a repository: its ids must resolve inside
		// .okf/vendor before anything is installed there or rolled back from there.
		vendorDisplay := filepath.Join(".okf", "vendor", filepath.FromSlash(entry.ID))
		vendorDir, err := registry.ResolveVendorDir(".", entry.ID)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: refusing to restore okf.lock entry: %v\n", err)
			exitFunc(1)
			return
		}
		indexFile := filepath.Join(vendorDir, "index.md")

		if _, err := os.Stat(indexFile); err == nil && !force {
			fmt.Printf("Bundle %q is already installed in %s (skipping)\n", entry.ID, vendorDisplay)
			skippedCount++
			continue
		}

		source := entry.Source
		if source == "" {
			source = entry.ID
		}
		if entry.Version != "" && !strings.Contains(source, "@") && entry.Version != "main" {
			source = fmt.Sprintf("%s@%s", source, entry.Version)
		}

		fmt.Printf("Resolving %s from %s...\n", entry.ID, client.BaseURL)
		manifest, err := client.Resolve(source)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error resolving %s: %v\n", entry.ID, err)
			exitFunc(1)
			return
		}

		if entry.Hash != "" {
			manifest.Hash = entry.Hash
		}

		fmt.Printf("Downloading %s (version: %s)...\n", manifest.ID, manifest.Version)
		// Extract and validate in a fresh staging directory: rollback discards
		// only what this invocation created, never an existing directory.
		staging, err := registry.NewStaging(".")
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: refusing to restore %s: %v\n", entry.ID, err)
			exitFunc(1)
			return
		}
		if err := client.DownloadAndExtract(manifest, staging.Dir); err != nil {
			_ = staging.Discard()
			fmt.Fprintf(os.Stderr, "Download error for %s: %v\n", manifest.ID, err)
			exitFunc(1)
			return
		}

		rollback := func() {
			if err := staging.Discard(); err != nil {
				fmt.Fprintf(os.Stderr, "Error: rollback refused: %v\n", err)
			}
		}

		if _, err := os.Stat(filepath.Join(staging.Dir, "index.md")); os.IsNotExist(err) {
			rollback()
			fmt.Fprintf(os.Stderr, "Error: bundle %q is not a valid OKF v0.2 bundle: missing index.md (installation rolled back)\n", manifest.ID)
			exitFunc(1)
			return
		}

		vb, err := okf.LoadBundle(staging.Dir)
		if err != nil {
			rollback()
			fmt.Fprintf(os.Stderr, "Error: bundle %q failed to load: %v (installation rolled back)\n", manifest.ID, err)
			exitFunc(1)
			return
		}

		diag := okf.Validate(vb, okf.ValidateOptions{
			Strict:   true,
			MinScore: minScore,
		})
		if !diag.IsConformant || !diag.GatePassed {
			rollback()
			if minScore > 0 && diag.Scorecard != nil && diag.Scorecard.Score < minScore {
				fmt.Fprintf(os.Stderr, "Error: bundle %q failed quality gate: score %d is below required minimum %d (Grade: %s); installation rolled back\n",
					manifest.ID, diag.Scorecard.Score, minScore, diag.Scorecard.Grade)
			} else {
				fmt.Fprintf(os.Stderr, "Error: bundle %q failed strict validation (%d errors, %d broken links); installation rolled back\n",
					manifest.ID, len(diag.Errors), len(diag.BrokenLinks))
			}
			exitFunc(1)
			return
		}

		if err := staging.Commit(".", entry.ID); err != nil {
			rollback()
			fmt.Fprintf(os.Stderr, "Error: bundle %q could not be restored: %v (installation rolled back)\n", manifest.ID, err)
			exitFunc(1)
			return
		}

		if diag.Scorecard != nil {
			fmt.Printf("Bundle quality score: %d/100 (Grade: %s)\n", diag.Scorecard.Score, diag.Scorecard.Grade)
		}
		fmt.Printf("Successfully restored %s in %s\n", manifest.ID, vendorDisplay)
		restoredCount++
	}

	fmt.Printf("Restore complete: %d restored, %d skipped.\n", restoredCount, skippedCount)
}

package cli

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/okf-memory/okf-agent-memory/pkg/lock"
	"github.com/okf-memory/okf-agent-memory/pkg/okf"
	"github.com/okf-memory/okf-agent-memory/pkg/registry"
)

var newRegistryClient = func(baseURL string) *registry.Client {
	return registry.NewClient(baseURL)
}

func printPullUsage() {
	fmt.Println(`Usage:
  okf pull [<bundle-id|git-url>] [flags]

Pulls and installs an external knowledge bundle into .okf/vendor/ and updates okf.lock.
If no bundle is specified, restores all bundles declared in okf.lock.

Flags:
  --registry <url>   Override canonical registry endpoint (default: https://registry.okf-memory.dev)
  --min-score <N>    Gate minimum bundle quality score (0-100; aborts installation if below)
  --force            Overwrite existing vendor installation if present

Examples:
  okf pull
  okf pull nextjs-15
  okf pull nextjs-15 --min-score 80
  okf pull @peter/django-5-rules
  okf pull peter/django-5-rules@1.0.0
  okf pull github.com/acme/agent-rules@v1.0.0`)
}

func cmdPull(args []string) {
	fs := flag.NewFlagSet("pull", flag.ExitOnError)
	registryURL := fs.String("registry", registry.DefaultRegistryURL, "Registry endpoint")
	minScore := fs.Int("min-score", 0, "Gate minimum bundle quality score (0-100)")
	force := fs.Bool("force", false, "Overwrite existing vendor installation")
	fs.Usage = printPullUsage

	if err := fs.Parse(args); err != nil {
		os.Exit(2)
	}

	if *minScore < 0 || *minScore > 100 {
		fmt.Fprintf(os.Stderr, "Error: --min-score must be an integer between 0 and 100\n")
		exitFunc(2)
		return
	}

	if fs.NArg() < 1 {
		if _, err := os.Stat("okf.lock"); os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, "Error: okf.lock not found. Specify a bundle to pull (e.g. 'okf pull <bundle-id>') or run in a workspace with an existing okf.lock.")
			exitFunc(1)
			return
		}
		runRestore(*registryURL, *force, *minScore)
		return
	}

	target := fs.Arg(0)
	client := newRegistryClient(*registryURL)

	fmt.Printf("Resolving %s from %s...\n", target, client.BaseURL)
	manifest, err := client.Resolve(target)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		exitFunc(1)
		return
	}

	if manifest.Version == "main" && (strings.HasPrefix(target, "github.com/") || strings.HasPrefix(target, "https://")) {
		fmt.Fprintf(os.Stderr, "Warning: Pulling floating branch 'main'. Pin to @vX.Y.Z for reproducible builds.\n")
	}

	// The manifest id comes from the registry: it must resolve inside .okf/vendor
	// before anything is installed there or rolled back from there.
	vendorDisplay := filepath.Join(".okf", "vendor", filepath.FromSlash(manifest.ID))
	vendorDir, err := registry.ResolveVendorDir(".", manifest.ID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: refusing to install bundle: %v\n", err)
		exitFunc(1)
		return
	}
	if _, err := os.Stat(vendorDir); err == nil && !*force {
		fmt.Printf("Bundle %q is already installed in %s. Use --force to reinstall.\n", manifest.ID, vendorDisplay)
		return
	}

	fmt.Printf("Downloading %s (version: %s)...\n", manifest.ID, manifest.Version)
	// Extract and validate in a fresh staging directory: rollback discards only
	// what this invocation created, never an existing directory.
	staging, err := registry.NewStaging(".")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: refusing to install bundle: %v\n", err)
		exitFunc(1)
		return
	}
	if err := client.DownloadAndExtract(manifest, staging.Dir); err != nil {
		_ = staging.Discard()
		fmt.Fprintf(os.Stderr, "Download error: %v\n", err)
		exitFunc(1)
		return
	}

	// Post-install validation: ensure installed bundle conforms to OKF v0.2 and passes quality gate
	rollback := func() {
		if err := staging.Discard(); err != nil {
			fmt.Fprintf(os.Stderr, "Error: rollback refused: %v\n", err)
		}
	}

	if _, err := os.Stat(filepath.Join(staging.Dir, "index.md")); os.IsNotExist(err) {
		rollback()
		fmt.Fprintf(os.Stderr, "Error: bundle %q is not a valid OKF v0.2 bundle: missing index.md (installation rolled back)\n", manifest.ID)
		exitFunc(1)
		return
	}

	vb, err := okf.LoadBundle(staging.Dir)
	if err != nil {
		rollback()
		fmt.Fprintf(os.Stderr, "Error: bundle %q failed to load: %v (installation rolled back)\n", manifest.ID, err)
		exitFunc(1)
		return
	}

	diag := okf.Validate(vb, okf.ValidateOptions{
		Strict:   true,
		MinScore: *minScore,
	})
	if !diag.IsConformant || !diag.GatePassed {
		rollback()
		if *minScore > 0 && diag.Scorecard != nil && diag.Scorecard.Score < *minScore {
			fmt.Fprintf(os.Stderr, "Error: bundle %q failed quality gate: score %d is below required minimum %d (Grade: %s); installation rolled back\n",
				manifest.ID, diag.Scorecard.Score, *minScore, diag.Scorecard.Grade)
		} else {
			fmt.Fprintf(os.Stderr, "Error: bundle %q failed strict validation (%d errors, %d broken links); installation rolled back\n",
				manifest.ID, len(diag.Errors), len(diag.BrokenLinks))
		}
		exitFunc(1)
		return
	}

	if err := staging.Commit(".", manifest.ID); err != nil {
		rollback()
		fmt.Fprintf(os.Stderr, "Error: bundle %q could not be installed: %v (installation rolled back)\n", manifest.ID, err)
		exitFunc(1)
		return
	}

	lockPath := "okf.lock"
	lf, err := lock.ReadLockfile(lockPath)
	if err != nil {
		lf = &lock.Lockfile{Version: 1}
	}
	lf.Upsert(lock.BundleEntry{
		ID:          manifest.ID,
		Source:      target,
		Version:     manifest.Version,
		Hash:        manifest.Hash,
		InstalledAt: time.Now().UTC(),
	})
	if err := lock.WriteLockfile(lockPath, lf); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to update okf.lock: %v\n", err)
	}

	if diag.Scorecard != nil {
		fmt.Printf("Bundle quality score: %d/100 (Grade: %s)\n", diag.Scorecard.Score, diag.Scorecard.Grade)
	}
	fmt.Printf("Successfully installed and verified %s in %s\n", manifest.ID, vendorDisplay)
}
